export type MessageKey = keyof typeof messages;
export type MessageValues = Record<string, string | number>;

const singularMessages: Partial<Record<Locale, Partial<Record<MessageKey, string>>>> = {
  en: {
    "{count} attempts": "{count} attempt",
    "{count} articles": "{count} article",
    "{count} parts": "{count} part",
    "{count} paired devices": "{count} paired device",
    "{count} projects": "{count} project",
    "{count} results": "{count} result",
    "{count} records": "{count} record",
    "{count} tool calls": "{count} tool call",
    "{count} reported turns": "{count} reported turn",
    "{count} members joined": "{count} member joined",
    "{count} calls": "{count} call",
    "{count} invites": "{count} invite",
    "{count} estimated tokens": "{count} estimated token",
    "{count} stars": "{count} star",
    "{count} plugins": "{count} plugin",
    "{count} links": "{count} link",
    "{count} nodes": "{count} node",
    "{count} relationships": "{count} relationship",
    "{count} tools ready": "{count} tool ready",
    "{count} devices ready": "{count} device ready",
    "{name} connected. {count} tools discovered on the selected device.": "{name} connected. {count} tool discovered on the selected device.",
  },
  hi: { "{count} projects": "{count} परियोजना", "{count} stars": "{count} सितारा", "{count} series": "{count} श्रृंखला" },
};

export function translate(locale: Locale, key: MessageKey, values: MessageValues = {}): string {
  const index = { vi: 0, "zh-Hans": 1, hi: 2 } as const;
  let template: string = locale === "en" ? key : messages[key][index[locale]];
  if (typeof values.count === "number" && new Intl.PluralRules(locale).select(values.count) === "one") {
    template = singularMessages[locale]?.[key] ?? template;
  }
  return template.replace(/\{(\w+)\}/g, (placeholder, name: string) => {
    const value = values[name];
    if (value === undefined) return placeholder;
    return typeof value === "number" ? new Intl.NumberFormat(locale).format(value) : value;
  });
}

// ponytail: Exact UI-message matches only; use backend message codes for new APIs.
export function translateKnownMessage(locale: Locale, message: string, values?: MessageValues): string {
  return Object.hasOwn(messages, message) ? translate(locale, message as MessageKey, values) : message;
}
